\documentclass{article}
% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{arrows.meta,shapes.geometric,positioning,fit,backgrounds}
\pagestyle{empty}

% ── IEEE S&P Color Theme: Deep Navy / Electric Blue / Teal ──
\definecolor{primary}{HTML}{0A1628}      % deep navy
\definecolor{secondary}{HTML}{1A3A6B}    % dark blue
\definecolor{accent}{HTML}{0EA5E9}       % electric blue
\definecolor{tealhi}{HTML}{0D9488}       % teal highlight
\definecolor{bgposter}{HTML}{F0F4F8}     % cool light gray background
\definecolor{redbg}{HTML}{EFF6FF}        % blue tint for cards
\definecolor{bluebg}{HTML}{F0FDFA}       % teal tint
\definecolor{darkbg}{HTML}{F1F5F9}       % slate tint
\definecolor{redtitlebg}{HTML}{DBEAFE}   % card title tints
\definecolor{bluetitlebg}{HTML}{CCFBF1}
\definecolor{darktitlebg}{HTML}{E2E8F0}
\definecolor{stathighlight}{HTML}{E0F2FE} % stat callout bg
\definecolor{stathl2}{HTML}{CCFBF1}
\definecolor{stathl3}{HTML}{FEF3C7}
\definecolor{textdark}{HTML}{0F172A}
\definecolor{textgray}{HTML}{475569}
\definecolor{warnyellow}{HTML}{F59E0B}
\definecolor{warnyellowbg}{HTML}{FFFBEB}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=5pt, parsep=1pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=5pt, parsep=1pt, topsep=2pt,
  label={\color{secondary}\bfseries\arabic*.}}

% ── Card styles (left accent stripe design) ──
\tcbset{
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{tealhi},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{tealhi},
    coltitle=tealhi, colbacktitle=bluetitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={tealhi!40},
    valign=top, drop shadow={opacity=0.15},
  },
  slatecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=darktitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!14!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.20},
  },
  warncard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=warnyellowbg,
    borderline west={5pt}{0pt}{warnyellow},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{warnyellow},
    coltitle=warnyellow, colbacktitle={warnyellow!15!white},
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={warnyellow!40},
    valign=top, drop shadow={opacity=0.15},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════
% TITLE BAR
% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=32pt, right=32pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{52}{62}\selectfont\bfseries\color{white}
    Bot Mitigation at Scale}\\[6pt]
  {\fontsize{36}{44}\selectfont\bfseries\color{accent}
    Protecting Scientific Publishing Platforms}\\[8pt]
  {\fontsize{24}{30}\selectfont\color{white!80}
    CDN-Based Verification Pipelines Against Automated Threats}\\[10pt]
  {\fontsize{20}{26}\selectfont\color{white!60}
    IEEE Symposium on Security and Privacy (S\&P) \ \ $\bullet$\ \  Security Research Track}
}

% ══════════════════════════════════════════════
% STAT BANNER — 3 callouts
% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!10!bgposter, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=8pt, bottom=8pt,
  valign=center,
  borderline south={2.5pt}{0pt}{primary!25},
  borderline north={2.5pt}{0pt}{primary!25},
]{name=stats, column=1, span=3, between=row4 and row7}{
  \centering
  % Stat 1 — 85% reduction (hero stat)
  \begin{minipage}[c]{0.305\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{secondary} 85\%}\\[2pt]
      {\fontsize{20}{26}\selectfont\bfseries\color{secondary} Reduction in Scraping}\\[1pt]
      {\fontsize{18}{24}\selectfont\color{textgray} after CDN deployment}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  % Stat 2 — 99.97% uptime
  \begin{minipage}[c]{0.305\linewidth}\centering
    \fcolorbox{tealhi!60}{stathl2}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{tealhi} 99.97\%}\\[2pt]
      {\fontsize{20}{26}\selectfont\bfseries\color{tealhi} Platform Uptime}\\[1pt]
      {\fontsize{18}{24}\selectfont\color{textgray} during 10$\times$ surge events}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  % Stat 3 — 47% bot traffic
  \begin{minipage}[c]{0.305\linewidth}\centering
    \fcolorbox{warnyellow!60}{stathl3}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{warnyellow} 47\%}\\[2pt]
      {\fontsize{20}{26}\selectfont\bfseries\color{warnyellow} of Internet Traffic}\\[1pt]
      {\fontsize{18}{24}\selectfont\color{textgray} is automated bots (2024)}\vspace{5pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════
% COLUMN 1 — THREAT LANDSCAPE + PERFORMANCE TABLE
% ══════════════════════════════════════════════
\posterbox[navycard, title={The Bot Threat Landscape}
]{name=threat, column=1, between=row7 and row13}{
  \fontsize{22}{30}\selectfont
  \begin{itemize}
    \item \textbf{47\%} of all internet traffic in 2024 originated from bots
    \item \textbf{30\%} of bots classified as malicious; academic publishers disproportionately targeted
    \item High-value content (DOIs, full-text articles) makes publishers prime scraping targets
    \item Attacks include: bulk scraping, credential stuffing, and coordinated DoS surges
  \end{itemize}

  \vspace{6pt}
  \colorbox{secondary!18}{\parbox{0.94\linewidth}{%
    \fontsize{21}{28}\selectfont\centering
    \textbf{www.science.org} (AAAS) serves millions globally\\
    and faced $\sim$\textbf{1.2M} scraping attempts/day pre-mitigation
  }}
}

\posterbox[tealcard, title={Performance Outcomes}
]{name=perftable, column=1, between=row13 and row20}{
  \fontsize{20}{28}\selectfont
  \renewcommand{\arraystretch}{1.55}
  \begin{tabular}{@{}p{0.42\linewidth}p{0.24\linewidth}p{0.24\linewidth}@{}}
    \rowcolor{secondary!15}
    \textbf{\color{secondary}Metric} & \textbf{\color{secondary}Before} & \textbf{\color{secondary}After} \\
    Scraping / day & 1.2M & 180K \\
    \rowcolor{accent!10}
    Origin CPU load & 78\% & 42\% \\
    User complaints / mo & 1,200 & 340 \\
    \rowcolor{accent!10}
    Uptime (surge) & 98.5\% & \textbf{99.97\%} \\
  \end{tabular}

  \vspace{8pt}
  \colorbox{tealhi!18}{\parbox{0.94\linewidth}{%
    \fontsize{20}{27}\selectfont\centering
    \textbf{$<$150 ms} added latency for verified sessions\\
    \textbf{$<$0.3\%} of legitimate users reported friction
  }}
}

% ══════════════════════════════════════════════
% COLUMN 2 — VERIFICATION PIPELINE (HERO)
% ══════════════════════════════════════════════
\posterbox[slatecard, title={Challenge-Based Verification Pipeline}
]{name=pipeline, column=2, between=row7 and row20}{
  \fontsize{21}{29}\selectfont
  \vspace{4pt}

  % Pipeline diagram using TikZ
  \begin{center}
  \begin{tikzpicture}[
    node distance=4mm,
    stagenode/.style={
      rectangle, rounded corners=3pt,
      minimum width=56mm, minimum height=11mm,
      text width=54mm, align=center,
      font=\fontsize{18}{22}\selectfont\bfseries,
    },
    timenode/.style={
      rectangle, rounded corners=2pt,
      minimum width=24mm, minimum height=8mm,
      align=center,
      font=\fontsize{16}{20}\selectfont,
    },
    arrow/.style={-{Stealth[scale=1.3]}, line width=1.8pt, color=accent},
    blocking/.style={
      rectangle, rounded corners=2pt,
      minimum width=28mm, minimum height=9mm,
      align=center, text width=26mm,
      font=\fontsize{16}{20}\selectfont,
    },
  ]
  % Stage nodes
  \node[stagenode, fill=secondary!20, draw=secondary, line width=1.2pt]
    (s1) {\color{secondary}1.\ Request Interception};
  \node[stagenode, fill=secondary!15, draw=secondary, line width=1pt, below=of s1]
    (s2) {\color{secondary}2.\ Threat Scoring};
  \node[stagenode, fill=accent!18, draw=accent, line width=1.5pt, below=of s2]
    (s3) {\color{accent!80!black}3.\ Challenge Issuance};
  \node[stagenode, fill=secondary!12, draw=secondary, line width=1pt, below=of s3]
    (s4) {\color{secondary}4.\ Verification Check};
  \node[stagenode, fill=tealhi!22, draw=tealhi, line width=1.5pt, below=of s4]
    (s5) {\color{tealhi}5.\ Access Granted};

  % Timing labels
  \node[timenode, fill=stathighlight, draw=accent!40, right=8mm of s1]
    (t1) {\color{secondary}$<$50 ms};
  \node[timenode, fill=stathighlight, draw=accent!40, right=8mm of s2]
    (t2) {\color{secondary}$\sim$100 ms};
  \node[timenode, fill=accent!15, draw=accent, line width=1.2pt, right=8mm of s3]
    (t3) {\color{accent!80!black}$\sim$500 ms};
  \node[timenode, fill=stathighlight, draw=accent!40, right=8mm of s4]
    (t4) {\color{secondary}$\sim$200 ms};
  \node[timenode, fill=stathl2, draw=tealhi, line width=1.2pt, right=8mm of s5]
    (t5) {\color{tealhi}$<$50 ms};

  % Arrows
  \draw[arrow] (s1) -- (s2);
  \draw[arrow] (s2) -- (s3);
  \draw[arrow] (s3) -- (s4);
  \draw[arrow] (s4) -- (s5);

  % Bot blocked branch
  \node[blocking, fill=red!12, draw=red!50, line width=1pt,
        left=10mm of s3] (blocked) {\color{red!70!black}\textbf{Bot\\Blocked}};
  \draw[-{Stealth[scale=1.1]}, line width=1.5pt, color=red!60, dashed]
    (s2.west) -- (blocked.east)
    node[midway, above, font=\fontsize{15}{18}\selectfont, color=red!60] {high risk};

  \end{tikzpicture}
  \end{center}

  \vspace{4pt}
  \colorbox{accent!15}{\parbox{0.94\linewidth}{%
    \centering\fontsize{20}{27}\selectfont
    \textbf{CDN edge intercepts} HTTP requests before origin\\
    IP reputation + TLS fingerprint + behavioral signals
  }}

  \vspace{6pt}
  \begin{itemize}
    \item JS/CAPTCHA challenge blocks scripts lacking browser runtime
    \item Each session assigned a traceable \textbf{Ray ID} for audit logging
    \item Total pipeline: \textbf{$<$2 seconds} for legitimate human users
    \item Automated scripts: \textbf{blocked entirely} at Stage 3
  \end{itemize}

  \vspace{6pt}
  \colorbox{secondary!15}{\parbox{0.94\linewidth}{%
    \centering\fontsize{20}{27}\selectfont
    \textit{Example Ray ID:} \texttt{\color{accent}9edb9b44499904f9}\\
    Enables per-request tracing \& continuous optimization
  }}
}

% ══════════════════════════════════════════════
% COLUMN 3 — TRADE-OFFS + KEY TAKEAWAYS
% ══════════════════════════════════════════════
\posterbox[warncard, title={Usability vs. Security Trade-offs}
]{name=tradeoffs, column=3, between=row7 and row14}{
  \fontsize{22}{30}\selectfont

  \colorbox{warnyellow!15}{\parbox{0.94\linewidth}{%
    \fontsize{21}{28}\selectfont
    \textbf{The tension:} blocking bots must not harm legitimate researchers
  }}

  \vspace{8pt}
  \begin{itemize}
    \item \textbf{Accessibility} — Challenge pages must comply with WCAG 2.1; screen-reader support is non-negotiable
    \item \textbf{Institutional Access} — University IP ranges allowlisted to reduce campus friction
    \item \textbf{Transparency} — Clear UI copy during verification reduces user confusion and abandonment
    \item \textbf{Privacy} — CDN data practices disclosed; threat signals balanced against user privacy
  \end{itemize}

  \vspace{6pt}
  \colorbox{warnyellow!18}{\parbox{0.94\linewidth}{%
    \centering\fontsize{20}{26}\selectfont
    User complaints: \textbf{1,200/month} $\to$ \textbf{340/month}\\
    Even after aggressive mitigation deployment
  }}
}

\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=3, between=row14 and row20}{
  \fontsize{22}{30}\selectfont
  \begin{enumerate}
    \item Bot traffic is a \textbf{structural threat} — nearly half of all requests to academic publishers are automated
    \item CDN-edge verification \textbf{dramatically reduces} scraping with minimal human impact ($<$0.3\% friction)
    \item \textbf{Quantitative monitoring} via Ray IDs enables continuous security-usability optimization
    \item \textbf{Publisher--CDN collaboration} is essential for sustaining secure, open access to scientific knowledge
  \end{enumerate}

  \vspace{8pt}
  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \centering\fontsize{20}{27}\selectfont
    \textbf{Implication for security community:}\\
    Challenge-based pipelines are production-ready,\\
    high-efficacy defenses for high-value web properties
  }}
}

\end{tcbposter}
\end{document}

